-- =========================================================
-- PRESENX SCHEMA & DADOS OFICIAIS LIMPOS (SUPABASE POSTGRESQL)
-- =========================================================

-- Desabilita avisos de chave estrangeira durante a criação
SET client_min_messages TO warning;

-- 1. TABELAS
CREATE TABLE IF NOT EXISTS pavilhoes (
  id TEXT PRIMARY KEY,
  nome TEXT NOT NULL,
  ordem INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS turnos_horarios (
  id SERIAL PRIMARY KEY,
  turno TEXT NOT NULL,
  chave TEXT NOT NULL,
  inicio TEXT NOT NULL,
  fim TEXT NOT NULL,
  ordem INTEGER DEFAULT 0,
  UNIQUE(turno, chave)
);

CREATE TABLE IF NOT EXISTS turmas (
  id TEXT PRIMARY KEY,
  nome TEXT NOT NULL,
  turno TEXT NOT NULL,
  pavilhao_id TEXT NOT NULL DEFAULT 'acm',
  sala_nome TEXT NOT NULL DEFAULT '',
  ordem INTEGER DEFAULT 0,
  FOREIGN KEY(pavilhao_id) REFERENCES pavilhoes(id) ON DELETE SET DEFAULT
);

CREATE TABLE IF NOT EXISTS disciplinas (
  id SERIAL PRIMARY KEY,
  nome TEXT UNIQUE NOT NULL,
  codigo TEXT DEFAULT '',
  cor_badge TEXT DEFAULT '#2563eb'
);

CREATE TABLE IF NOT EXISTS usuarios (
  uid TEXT PRIMARY KEY,
  nome TEXT NOT NULL,
  curso TEXT DEFAULT '',
  ativo INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS professores_disciplinas (
  professor_uid TEXT NOT NULL REFERENCES usuarios(uid) ON DELETE CASCADE,
  disciplina_id INTEGER NOT NULL REFERENCES disciplinas(id) ON DELETE CASCADE,
  PRIMARY KEY (professor_uid, disciplina_id)
);

CREATE TABLE IF NOT EXISTS grade_horarios (
  id SERIAL PRIMARY KEY,
  turma_id TEXT NOT NULL REFERENCES turmas(id) ON DELETE CASCADE,
  dia TEXT NOT NULL,
  horario INTEGER NOT NULL,
  disciplina TEXT NOT NULL,
  professor TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS presencas (
  id SERIAL PRIMARY KEY,
  data TEXT NOT NULL,
  uid TEXT NOT NULL,
  nome TEXT NOT NULL,
  curso TEXT DEFAULT '',
  status TEXT NOT NULL,
  hora_entrada TEXT,
  hora_saida TEXT
);

CREATE TABLE IF NOT EXISTS avisos (
  id SERIAL PRIMARY KEY,
  titulo TEXT NOT NULL,
  mensagem TEXT NOT NULL,
  prioridade TEXT NOT NULL DEFAULT 'normal',
  expiracao TEXT NOT NULL DEFAULT '',
  ativo INTEGER NOT NULL DEFAULT 1,
  criado_em BIGINT DEFAULT 0
);

CREATE TABLE IF NOT EXISTS eventos (
  id SERIAL PRIMARY KEY,
  titulo TEXT NOT NULL,
  descricao TEXT DEFAULT '',
  data TEXT NOT NULL,
  categoria TEXT DEFAULT 'evento'
);

CREATE TABLE IF NOT EXISTS admin_usuarios (
  id SERIAL PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  senha TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS admin_sessoes (
  token TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  expira_em BIGINT NOT NULL,
  criado_em TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS ultimo_acesso (
  chave TEXT PRIMARY KEY,
  uid TEXT,
  nome TEXT,
  curso TEXT,
  hora TEXT,
  data TEXT,
  status TEXT
);

CREATE TABLE IF NOT EXISTS leitores_rfid (
  id TEXT PRIMARY KEY,
  nome TEXT NOT NULL,
  local TEXT DEFAULT '',
  ip TEXT DEFAULT '',
  ultimo_ping BIGINT DEFAULT 0,
  total_leituras_hoje INTEGER DEFAULT 0
);

-- =========================================================
-- 2. DADOS INICIAIS / CARGA LIMPA
-- =========================================================
SELECT setval(pg_get_serial_sequence('disciplinas', 'id'), coalesce(max(id), 1)) FROM disciplinas;
SELECT setval(pg_get_serial_sequence('grade_horarios', 'id'), coalesce(max(id), 1)) FROM grade_horarios;
